class Solution {
public:
    vector<int> canSeePersonsCount(vector<int>& heights) {
        int n = heights.size();
        vector<int> res(n, 0);
        vector<int> st;
        for (int i = n - 1; i >= 0; i--) {
            int h = heights[i];
            while (!st.empty() && h > st.back()) {
                st.pop_back();
                res[i]++;
            }
            if (!st.empty()) res[i]++;
            st.push_back(h);
        }
        return res;
    }
};

class Solution {
    public int[] canSeePersonsCount(int[] heights) {
        int n = heights.length;
        int[] res = new int[n];
        int[] st = new int[n];
        int top = 0;
        for (int i = n - 1; i >= 0; i--) {
            int h = heights[i];
            while (top > 0 && h > st[top - 1]) {
                top--;
                res[i]++;
            }
            if (top > 0) res[i]++;
            st[top++] = h;
        }
        return res;
    }
}

var canSeePersonsCount = function(heights) {
    const n = heights.length;
    const res = new Array(n).fill(0);
    const st = [];
    for (let i = n - 1; i >= 0; i--) {
        const h = heights[i];
        while (st.length > 0 && h > st[st.length - 1]) {
            st.pop();
            res[i]++;
        }
        if (st.length > 0) res[i]++;
        st.push(h);
    }
    return res;
};
